import os
import hashlib
import hmac
import re
import secrets
from pathlib import Path, PurePosixPath
from flask import Flask, request, jsonify, session, abort
import argon2

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

BASE_DIR = Path('/srv/documents')
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.docx', '.xlsx', '.csv', '.json'}
MAX_PATH_DEPTH = 5
API_KEYS = {}

ph = argon2.PasswordHasher()

def generate_api_key(user_id: str) -> str:
    key = secrets.token_urlsafe(32)
    API_KEYS[user_id] = ph.hash(key)
    return key

def verify_api_key(user_id: str, key: str) -> bool:
    if user_id not in API_KEYS:
        return False
    try:
        return ph.verify(API_KEYS[user_id], key)
    except (argon2.exceptions.VerifyMismatchError,
            argon2.exceptions.InvalidHashError,
            argon2.exceptions.VerificationError):
        return False

def sanitize_path_component(component: str) -> str:
    """Remove dangerous characters from a single path component."""
    # Strip null bytes
    component = component.replace('\x00', '')
    # Remove any path separators
    component = component.replace('/', '').replace('\\', '')
    # Only allow alphanumeric, hyphen, underscore, and a single dot for extension
    if not re.match(r'^[a-zA-Z0-9_\-]+(\.[a-zA-Z0-9]+)?$', component):
        raise ValueError(f"Invalid path component: {component}")
    return component

def validate_path(user_path: str) -> Path:
    """Validate and resolve a user-supplied path against BASE_DIR.

    Security: normalizes the path, checks each component with strict regex,
    verifies the resolved path is under BASE_DIR.
    """
    # Normalize unicode to NFC form
    import unicodedata
    user_path = unicodedata.normalize('NFC', user_path)

    # Reject obviously malicious patterns
    if '\x00' in user_path:
        raise ValueError("Null bytes not allowed")

    # Split into components and sanitize each
    parts = PurePosixPath(user_path).parts

    # Remove leading slash if present
    if parts and parts[0] == '/':
        parts = parts[1:]

    if len(parts) > MAX_PATH_DEPTH:
        raise ValueError("Path too deep")

    if not parts:
        raise ValueError("Empty path")

    # Sanitize each component individually with strict regex
    clean_parts = []
    for part in parts:
        clean = sanitize_path_component(part)
        clean_parts.append(clean)

    if not clean_parts:
        raise ValueError("Empty path")

    # Construct the full path
    target = BASE_DIR
    for part in clean_parts:
        target = target / part

    # Check extension
    if target.suffix.lower() not in ALLOWED_EXTENSIONS:
        raise ValueError(f"Extension {target.suffix} not allowed")

    # Final resolution check - resolve symlinks and verify containment
    # Use os.path.commonpath for robust containment check
    resolved = target.resolve()
    base_resolved = BASE_DIR.resolve()
    try:
        resolved.relative_to(base_resolved)
    except ValueError:
        raise ValueError("Path escapes base directory")

    return resolved

@app.route('/api/auth', methods=['POST'])
def authenticate():
    data = request.get_json()
    if not data or 'user_id' not in data or 'api_key' not in data:
        abort(401)
    if verify_api_key(data['user_id'], data['api_key']):
        session['user_id'] = data['user_id']
        session['authenticated'] = True
        return jsonify({'status': 'ok'})
    abort(401)

@app.route('/api/documents/<path:filepath>', methods=['GET'])
def get_document(filepath: str):
    if not session.get('authenticated'):
        abort(401)

    try:
        resolved = validate_path(filepath)
    except ValueError as e:
        abort(400, description=str(e))

    if not resolved.exists():
        abort(404)

    return resolved.read_bytes()

@app.route('/api/documents/<path:filepath>', methods=['PUT'])
def put_document(filepath: str):
    if not session.get('authenticated'):
        abort(401)

    try:
        resolved = validate_path(filepath)
    except ValueError as e:
        abort(400, description=str(e))

    resolved.parent.mkdir(parents=True, exist_ok=True)
    resolved.write_bytes(request.get_data())
    return jsonify({'status': 'created', 'path': str(resolved)})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
